WordHunterWoW_QuestEN[7640] = { title = "Exorcising Terrordale", description = "", objectives = "Use the Exorcism Censer to drive out the spirits that torment Terrordale. When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." }
WordHunterWoW_QuestEN[7641] = { title = "The Work of Grimand Elmore", description = "", objectives = "Speak with Grimand Elmore in Stormwind's Dwarven District." }
WordHunterWoW_QuestEN[7642] = { title = "Collection of Goods", description = "", objectives = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind." }
WordHunterWoW_QuestEN[7643] = { title = "Ancient Equine Spirit", description = "", objectives = "Acquire special horse feed used for feeding a spirit horse. Merideth Carlson in Southshore apparently is the source for such food.\nTravel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood. Doing so will free the Ancient Equine Spirit. Feed it the special horse feed, thereby soothing the spirit. Finally, give it the Arcanite Barding so it may bless it." }
WordHunterWoW_QuestEN[7644] = { title = "Blessed Arcanite Barding", description = "", objectives = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." }
WordHunterWoW_QuestEN[7645] = { title = "Manna-Enriched Horse Feed", description = "", objectives = "Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills. The Argent Dawn is known as the sole purveyor of the biscuits.\nYou also need to give her 50 gold to soothe her ruffled sensibilities." }
WordHunterWoW_QuestEN[7646] = { title = "The Divination Scryer", description = "", objectives = "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." }
WordHunterWoW_QuestEN[7647] = { title = "Judgment and Redemption", description = "", objectives = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth the spirits you must judge. Defeating these spirits will summon forth Death Knight Darkreaver. Defeat him and reclaim the lost soul of the fallen charger.\nGive the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger." }
WordHunterWoW_QuestEN[7648] = { title = "Grimand's Finest Work", description = "", objectives = "Take the Arcanite Barding to Lord Grayson Shadowbreaker in Stormwind's Cathedral District for his inspection." }
WordHunterWoW_QuestEN[7649] = { title = "Enchanted Thorium Platemail: Volume I", description = "", objectives = "Return the book to its rightful owners." }
WordHunterWoW_QuestEN[7650] = { title = "Enchanted Thorium Platemail: Volume II", description = "", objectives = "Return the book to its rightful owners." }
