WordHunterWoW_QuestEN[7677] = { title = "White Stallion Exchange", description = "", objectives = "If you bring me your white stallion, I'll trade you for one from the new herd. The new horse will be just as fast as your old one, but have a different look to it. You can look at the swift steeds here to see what it will look like.\nMUST PAY 500 Gold too...." }
