WordHunterWoW_QuestEN[7701] = { title = "WANTED: Overseer Maltorius", description = "", objectives = "Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.\nSlay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward." }
WordHunterWoW_QuestEN[7703] = { title = "Unfinished Gordok Business", description = "", objectives = "Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.\nAccording to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings." }
WordHunterWoW_QuestEN[7704] = { title = "Look at the Size of It!", description = "", objectives = "Take Chambermaid Pillaclencher's Pillow to Evonice Sootsmoker in the Searing Gorge." }
WordHunterWoW_QuestEN[7721] = { title = "Fuel for the Zapping", description = "", objectives = "Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there." }
WordHunterWoW_QuestEN[7722] = { title = "What the Flux?", description = "", objectives = "Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge." }
WordHunterWoW_QuestEN[7723] = { title = "Curse These Fat Fingers", description = "", objectives = "Hansel Heavyhands wants you to kill 20 Heavy War Golems.\nThe Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge." }
WordHunterWoW_QuestEN[7724] = { title = "Fiery Menace!", description = "", objectives = "Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.\nReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders." }
WordHunterWoW_QuestEN[7725] = { title = "Again With the Zapped Giants", description = "", objectives = "Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form. Bring 10 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas." }
WordHunterWoW_QuestEN[7726] = { title = "Refuel for the Zapping", description = "", objectives = "Collect 6 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there." }
WordHunterWoW_QuestEN[7727] = { title = "Incendosaurs? Whateverosaur is More Like It", description = "", objectives = "Hansel Heavyhands wants you to kill 20 Incendosaurs.\nYou will find Incendosaurs occupying the lava pools inside the Slag Pit. The Slag Pit can be found in the Cauldron of the Searing Gorge.\nReturn to Hansel Heavyhands in the Searing Gorge when you have killed enough Incendosaurs." }
WordHunterWoW_QuestEN[7728] = { title = "STOLEN: Smithing Tuyere and Lookout's Spyglass", description = "", objectives = "Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge.\nThe only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout's Spyglass is an invaluable monitoring tool to lookouts." }
WordHunterWoW_QuestEN[7729] = { title = "JOB OPPORTUNITY: Culling the Competition", description = "", objectives = "Slay 15 Dark Iron Taskmasters and 15 Dark Iron Slavers. Return to Taskmaster Scrange in the Searing Gorge once you have accomplished this task." }
WordHunterWoW_QuestEN[7730] = { title = "Zukk'ash Infestation", description = "", objectives = "Bring 20 Zukk'ash Carapaces to Hadoken Swiftstrider at Camp Mojache, Feralas." }
WordHunterWoW_QuestEN[7731] = { title = "Stinglasher", description = "", objectives = "Defeat Stinglasher in the Writhing Deep, bringing its glands back to Hadoken Swiftstrider at Camp Mojache, Feralas." }
WordHunterWoW_QuestEN[7732] = { title = "Zukk'ash Report", description = "", objectives = "Deliver the Camp Mojache Zukk'ash Report to Zilzibin Drumlore. He resides in the Drag of Orgrimmar." }
WordHunterWoW_QuestEN[7733] = { title = "Improved Quality", description = "", objectives = "Bring 10 Rage Scar Yeti Hides to Pratt McGrubben at Feathermoon Stronghold, Feralas." }
WordHunterWoW_QuestEN[7734] = { title = "Improved Quality", description = "", objectives = "Bring 10 Rage Scar Yeti Hides to Jangdor Swiftstrider at Camp Mojache, Feralas." }
WordHunterWoW_QuestEN[7735] = { title = "Pristine Yeti Hide", description = "", objectives = "Bring the Pristine Yeti Hide to Pratt McGrubben at the Feathermoon Stronghold, Feralas." }
WordHunterWoW_QuestEN[7736] = { title = "Restoring Fiery Flux Supplies via Kingsblood", description = "", objectives = "Deliver 2 Incendosaur Scales, 4 Kingsblood and one Coal to Master Smith Burninate." }
WordHunterWoW_QuestEN[7737] = { title = "Gaining Acceptance", description = "", objectives = "" }
WordHunterWoW_QuestEN[7738] = { title = "Perfect Yeti Hide", description = "", objectives = "Bring the Perfect Yeti Hide to Jangdor Swiftstrider at Camp Mojache, Feralas." }
WordHunterWoW_QuestEN[7761] = { title = "Blackhand's Command", description = "", objectives = "That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.\nThe letter indicates that General Drakkisath guards the brand. Perhaps you should investigate." }
WordHunterWoW_QuestEN[7781] = { title = "The Lord of Blackrock", description = "", objectives = "Return the Head of Nefarian to Highlord Bolvar Fordragon in Stormwind." }
WordHunterWoW_QuestEN[7782] = { title = "The Lord of Blackrock", description = "", objectives = "Venture to the Valley of Heroes in Stormwind City and speak with Field Marshal Afrasiabi." }
WordHunterWoW_QuestEN[7783] = { title = "The Lord of Blackrock", description = "", objectives = "Return the Head of Nefarian to Thrall in Orgrimmar." }
WordHunterWoW_QuestEN[7784] = { title = "The Lord of Blackrock", description = "", objectives = "Speak with High Overlord Saurfang in Orgrimmar. He stands waiting for you in the Valley of Strength." }
WordHunterWoW_QuestEN[7785] = { title = "Examine the Vessel", description = "", objectives = "Examine the Vessel of Rebirth and return it to Highlord Demitrian." }
WordHunterWoW_QuestEN[7786] = { title = "Thunderaan the Windseeker", description = "", objectives = "To free Thunderaan the Windseeker from his prison, you must present the right and left halves of the Bindings of the Windseeker, 10 bars of Elementium, and the Essence of the Firelord to Highlord Demitrian in Silithus." }
WordHunterWoW_QuestEN[7787] = { title = "Rise, Thunderfury!", description = "", objectives = "Present the Dormant Wind Kissed Blade to Highlord Demitrian." }
