WordHunterWoW_QuestEN[7828] = { title = "Stalking the Stalkers", description = "", objectives = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 10 Silvermane Stalkers and 10 Silvermane Howlers. Return to him once the task is complete.\nMarkhor mentioned that the wolves hide in the wilds of the Hinterlands." }
WordHunterWoW_QuestEN[7829] = { title = "Hunt the Savages", description = "", objectives = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 20 Savage Owlbeasts. Return to him once the task is complete.\nMarkhor mentioned that the Savage Owlbeasts occupy the wilds of the Hinterlands." }
WordHunterWoW_QuestEN[7830] = { title = "Avenging the Fallen", description = "", objectives = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill a Razorbeak Skylord and retrieve its Skylord Plume. Return to him once the task is complete.\nMarkhor mentioned that the Razorbeak Skylord are a rare breed that tend to occupy the wilds of the Hinterlands." }
