WordHunterWoW_QuestEN[7839] = { title = "Vilebranch Hooligans", description = "", objectives = "Smith Slagtree at Revantusk Village in the Hinterlands wants you to find Slagtree's Lost Tools. Return to him once this task is complete.\nYou recall Smith Slagtree mentioning that the tools might be at one of the Vilebranch temples in the northeastern region of the Hinterlands. You should also check Skulk Rock." }
WordHunterWoW_QuestEN[7840] = { title = "Lard Lost His Lunch", description = "", objectives = "Lard at Revantusk Village in the Hinterlands wants you to find Lard's Lunch. Return to him when this task is complete.\nLard mentioned that he left it on the island to the north. Watch out for Vilebranch trolls." }
WordHunterWoW_QuestEN[7841] = { title = "Message to the Wildhammer", description = "", objectives = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to slaughter 15 Highvale Outrunners, 15 Highvale Scouts, 15 Highvale Marksman and 15 Highvale Rangers. Return to him when this task is complete.\nYou can find the Highvale high elves at the Quel'Danil Lodge in the northwestern region of the Hinterlands." }
WordHunterWoW_QuestEN[7842] = { title = "Another Message to the Wildhammer", description = "", objectives = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to bring him 10 Long Elegant Feathers from the gryphons that inhabit the Hinterlands. Return to him once this task is complete.\nGryphons are known to inhabit every region of the Hinterlands." }
WordHunterWoW_QuestEN[7843] = { title = "The Final Message to the Wildhammer", description = "", objectives = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to travel to Aerie Peak in the western region of the Hinterlands and place the Final Message to the Wildhammer by the well in the center of town. Return to him once this task is complete.\nBeware of angry Wildhammer dwarves and unruly members of the Alliance." }
WordHunterWoW_QuestEN[7844] = { title = "Cannibalistic Cousins", description = "", objectives = "Mystic Yayo'jin at Revantusk Village in the Hinterlands wants you to kill 30 Vilebranch Scalpers and 15 Vilebranch Soothsayers. Return to her when this task is complete.\nYayo'jin indicated that these trolls could be found near the Shaol'watha and Agol'watha temples in the north by northeastern region of the Hinterlands." }
WordHunterWoW_QuestEN[7845] = { title = "Kidnapped Elder Torntusk!", description = "", objectives = "Primal Torntusk at Revantusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha'alor.\nYou have been told that he is being held prisoner atop Jintha'alor, the Vilebranch capital city located in the southern region of the Hinterlands." }
WordHunterWoW_QuestEN[7846] = { title = "Recover the Key!", description = "", objectives = "Elder Torntusk at Jintha'alor wants you to kill Hitah'ya the Keeper to get the Shackle Key to his bindings. Return to Elder Torntusk when you have recovered the key." }
WordHunterWoW_QuestEN[7847] = { title = "Return to Primal Torntusk", description = "", objectives = "Elder Torntusk at Jintha'alor wants you to return to Primal Torntusk at Revantusk Village with news of his rescue." }
WordHunterWoW_QuestEN[7848] = { title = "Attunement to the Core", description = "", objectives = "Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment." }
WordHunterWoW_QuestEN[7849] = { title = "Separation Anxiety", description = "", objectives = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.\nMarkhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both of these places are near the top of the temple." }
WordHunterWoW_QuestEN[7850] = { title = "Dark Vessels", description = "", objectives = "Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 10 Vessels of Tainted Blood from Jintha'alor. Return to Primal Torntusk when this task is complete." }
WordHunterWoW_QuestEN[7861] = { title = "Wanted: Vile Priestess Hexx and Her Minions", description = "", objectives = "You have been ordered to slay Vile Priestess Hexx and 20 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.\nVile Priestess Hexx and the Aman'zasi Guards can be found atop Jintha'alor in the Hinterlands." }
WordHunterWoW_QuestEN[7862] = { title = "Job Opening: Guard Captain of Revantusk Village", description = "", objectives = "You have been tasked with the decimation of 20 Vilebranch Berserkers, 20 Vilebranch Shadow Hunters, 20 Vilebranch Blood Drinkers, and 20 Vilebranch Soul Eaters.\nShould you complete this task, return to Primal Torntusk at Revantusk Village in the Hinterlands." }
