WordHunterWoW_QuestEN[8306] = { title = "Into The Maw of Madness", description = "", objectives = "Commander Mar'alith at Cenarion Hold in Silithus wants you to find his beloved Natalia. The information that you gathered points to Hive'Regal in the south as being the area in which you may find Mistress Natalia Mar'alith.\nDo not forget to visit the dwarves at Bronzebeard's camp before venturing into the hive. They might have some additional work and advice for you.\nAnd $N, remember the Commander's words: \"Do what you must...\"" }
